/* From Uiverse.io by mrhyddenn - Tags: button */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  position: relative;
  text-align: center;
  display: block;
  width: 200px;
  border: none;
  font-size: 12px;
  height: 45px;
  text-decoration: none;
  font-weight: 600;
  overflow: hidden;
  box-shadow: 0 10px 50px #006eff;
  border-radius: 10px;
  padding: 10px 20px;
}

.__UIV_SCOPE__ .button .ten {
  line-height: 52px;
}

.__UIV_SCOPE__ .button:hover .slidein {
  left: 0%;
}

.__UIV_SCOPE__ .button:hover .two {
  left: 0%;
  transition-delay: 1.5s;
}

.__UIV_SCOPE__ .button:hover .three {
  left: 0%;
  transition-delay: 3s;
}

.__UIV_SCOPE__ .button:hover .four {
  left: 0%;
  transition-delay: 4.5s;
}

.__UIV_SCOPE__ .button:hover .five {
  left: 0%;
  transition-delay: 6s;
}

.__UIV_SCOPE__ .button:hover .six {
  left: 0%;
  transition-delay: 7.5s;
}

.__UIV_SCOPE__ .button:hover .seven {
  left: 0%;
  transition-delay: 9s;
}

.__UIV_SCOPE__ .button:hover .eight {
  left: 0%;
  transition-delay: 10.5s;
}

.__UIV_SCOPE__ .button:hover .nine {
  left: 0%;
  transition-delay: 12s;
}

.__UIV_SCOPE__ .button:hover .ten {
  left: 0%;
  transition-delay: 14s;
}

.__UIV_SCOPE__ .button .slidein {
  background: #3398ff;
  left: -100%;
  z-index: 2;
}

.__UIV_SCOPE__ .button a {
  text-transform: uppercase;
  transition: left 300ms;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 1px;
  background: #006eff;
  position: absolute;
  font-weight: bold;
  z-index: 1;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  color: #fff;
}

.__UIV_SCOPE__ .slidein:nth-child( even) {
  background: #348bfc !important;
}

.__UIV_SCOPE__ .slidein:nth-child( odd) {
  background: #0873ff !important;
}
